-- ============================================================
--  Experiencias de clase: Curso de Gestión de Calidad Farmacéutica
--
--  Generado por scripts/generar-experiencias-catalogo.mjs a partir del
--  resumen de cada clase, los enlaces verificados y el material de
--  evaluación de contenido/aula/catalogo. No editar a mano.
--
--  35 clases. No toca cursos con experiencia escrita a
--  mano ni clases que ya tenían texto largo aprobado.
-- ============================================================

DO $curso$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Gestión de Calidad Farmacéutica$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Gestión de Calidad Farmacéutica$t$;
    RETURN;
  END IF;

  -- 01. Introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos$t$
     AND m.title = $u$Unidad 1. Fundamentos de la gestión de calidad farmacéutica$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos$t$, $u$Unidad 1. Fundamentos de la gestión de calidad farmacéutica$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos","texto":"En una planta o un laboratorio farmacéutico colombiano, un proveedor cambia de planta y el certificado que llega no cubre la línea que fabrica el insumo. Lo que está en juego es el criterio de introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos con tus propias palabras y reconocer por qué importa en curso de Gestión de Calidad Farmacéutica.","Relacionar introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos con unidad 1. Fundamentos de la gestión de calidad farmacéutica y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"El estudiante conoce la ruta del curso, su alcance frente a los cursos hermanos (BPM, CAPA, auditoría, etc.) y por qué el QF colombiano necesita dominar el SGC."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos aparece en medio de una decisión que no admite improvisación: un proveedor cambia de planta y el certificado que llega no cubre la línea que fabrica el insumo. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de la gestión de calidad farmacéutica. El objetivo del curso es claro: Que el Químico Farmacéutico sea capaz de diseñar, implementar, medir y mejorar un sistema de gestión de calidad en una organización farmacéutica colombiana, integrando ICH Q10, ISO 9001:2015 y la normativa del INVIMA y MinSalud. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: El estudiante conoce la ruta del curso, su alcance frente a los cursos hermanos (BPM, CAPA, auditoría, etc.) y por qué el QF colombiano necesita dominar el SGC.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en requisito y en evidencia documentada, no en la intuición.","La clase pertenece a unidad 1. Fundamentos de la gestión de calidad farmacéutica y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Diagnóstico de madurez con los siete principios y plan de mejoras prioritarias.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y lista las siete situaciones observadas. Evidencia que debe quedar: Registro del paso.","Relaciona cada situación con el principio o los principios de ISO 9000 que no se están aplicando y explica por qué. Evidencia que debe quedar: Registro del paso.","Valora la madurez del laboratorio en cada principio con una escala de 1 a 4 que tú definas por escrito. Evidencia que debe quedar: Registro del paso.","Identifica qué situaciones afectan más al paciente y cuáles al cumplimiento de las BPM. Evidencia que debe quedar: Registro del paso.","Propón tres mejoras prioritarias, cada una con un indicador y un responsable. Evidencia que debe quedar: Registro del paso.","Redacta una conclusión de media página para la gerencia. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: cerrar una CAPA sin verificar eficacia Corrección: una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato.","Error: documentar después de ejecutar Corrección: el registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad.","Error: tratar todos los riesgos como iguales Corrección: priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos»?","respuesta":"El estudiante conoce la ruta del curso, su alcance frente a los cursos hermanos (BPM, CAPA, auditoría, etc.) y por qué el QF colombiano necesita dominar el SGC."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Diagnóstico de madurez con los siete principios y plan de mejoras prioritarias.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de la gestión de calidad farmacéutica.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"Masterclass - Gestión de la Calidad en la Industria Farmacéutica","url":"https://www.youtube.com/watch?v=RcaLx0s3GZY"},{"cita":"Rol del Sistema de Gestión de la Calidad SGC en la Industria Farmacéutica","url":"https://www.youtube.com/watch?v=BKZ1PhzGvO0"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos"}],"keywords":["curso","gestión","calidad","farmacéutica","introducción","sistema","industria","servicios","farmacéuticos","unidad","fundamentos"],"mapa":{"centro":"Introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 1. Fundamentos de la gestión de calidad farmacéutica","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se aplica: Diagnóstico de un laboratorio con los siete principios","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y lista las siete situaciones observadas.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Relaciona cada situación con el principio o los principios de ISO 9000 que no se están aplicando y explica por qué.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Valora la madurez del laboratorio en cada principio con una escala de 1 a 4 que tú definas por escrito.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Identifica qué situaciones afectan más al paciente y cuáles al cumplimiento de las BPM.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Propón tres mejoras prioritarias, cada una con un indicador y un responsable.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Redacta una conclusión de media página para la gerencia.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Diagnóstico de un laboratorio con los siete principios","contexto":"Laboratorio Andino de Genéricos (ficticio), de Bogotá, tiene 120 empleados y certificado de BPM. En una semana de observación se encontró (datos simulados): las decisiones de compra se toman por el precio sin evaluar proveedores; producción, control de calidad y bodega trabajan como islas y se culpan mutuamente de los retrasos; el personal no conoce la política de calidad, colgada en la recepción; los indicadores se calculan, pero nadie los analiza; las quejas subieron 40 % y se responden una a una sin buscar causas comunes; el gerente decide las prioridades «por experiencia»; y no hay un plan de mejora desde hace dos años.","pregunta":"¿Qué decisión demuestra que entendiste introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 02. Evolución histórica de la calidad: de la inspección a la gestión total
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Evolución histórica de la calidad: de la inspección a la gestión total$t$
     AND m.title = $u$Unidad 1. Fundamentos de la gestión de calidad farmacéutica$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Evolución histórica de la calidad: de la inspección a la gestión total$t$, $u$Unidad 1. Fundamentos de la gestión de calidad farmacéutica$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Evolución histórica de la calidad: de la inspección a la gestión total","texto":"En una planta o un laboratorio farmacéutico colombiano, un lote cumple las especificaciones, pero la revisión del expediente muestra una etapa sin verificar. Lo que está en juego es el criterio de evolución histórica de la calidad: de la inspección a la gestión total. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar evolución histórica de la calidad: de la inspección a la gestión total con tus propias palabras y reconocer por qué importa en curso de Gestión de Calidad Farmacéutica.","Relacionar evolución histórica de la calidad: de la inspección a la gestión total con unidad 1. Fundamentos de la gestión de calidad farmacéutica y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar evolución histórica de la calidad: de la inspección a la gestión total y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Describe las etapas de inspección, control estadístico, aseguramiento, calidad total y sistemas de gestión, y su reflejo en la regulación farmacéutica."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, evolución histórica de la calidad: de la inspección a la gestión total aparece en medio de una decisión que no admite improvisación: un lote cumple las especificaciones, pero la revisión del expediente muestra una etapa sin verificar. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de la gestión de calidad farmacéutica. El objetivo del curso es claro: Que el Químico Farmacéutico sea capaz de diseñar, implementar, medir y mejorar un sistema de gestión de calidad en una organización farmacéutica colombiana, integrando ICH Q10, ISO 9001:2015 y la normativa del INVIMA y MinSalud. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Describe las etapas de inspección, control estadístico, aseguramiento, calidad total y sistemas de gestión, y su reflejo en la regulación farmacéutica.","Una pregunta que se usa para comprobar esta clase es: «¿Qué distingue el aseguramiento de la calidad de la etapa de inspección en la evolución histórica de la calidad?» La respuesta correcta se apoya en lo siguiente: La calidad pasó de la inspección del producto terminado al control estadístico, luego al aseguramiento (prevenir con sistemas y procesos), a la calidad total y a los sistemas de gestión. La regulación farmacéutica refleja ese paso: las BPM buscan construir la calidad en el proceso. La fuente citada es: ISO 9000:2015, fundamentos; OMS TRS 986, anexo 2.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos de la gestión de calidad farmacéutica y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Diagnóstico de madurez con los siete principios y plan de mejoras prioritarias.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar evolución histórica de la calidad: de la inspección a la gestión total, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y lista las siete situaciones observadas. Evidencia que debe quedar: Registro del paso.","Relaciona cada situación con el principio o los principios de ISO 9000 que no se están aplicando y explica por qué. Evidencia que debe quedar: Registro del paso.","Valora la madurez del laboratorio en cada principio con una escala de 1 a 4 que tú definas por escrito. Evidencia que debe quedar: Registro del paso.","Identifica qué situaciones afectan más al paciente y cuáles al cumplimiento de las BPM. Evidencia que debe quedar: Registro del paso.","Propón tres mejoras prioritarias, cada una con un indicador y un responsable. Evidencia que debe quedar: Registro del paso.","Redacta una conclusión de media página para la gerencia. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: documentar después de ejecutar Corrección: el registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad.","Error: confundir el análisis final con la garantía de calidad Corrección: el muestreo no detecta todos los defectos; la calidad se construye durante el proceso.","Error: cerrar una CAPA sin verificar eficacia Corrección: una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar evolución histórica de la calidad: de la inspección a la gestión total en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Evolución histórica de la calidad: de la inspección a la gestión total»?","respuesta":"Describe las etapas de inspección, control estadístico, aseguramiento, calidad total y sistemas de gestión, y su reflejo en la regulación farmacéutica."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Diagnóstico de madurez con los siete principios y plan de mejoras prioritarias.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Evolución histórica de la calidad: de la inspección a la gestión total se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de la gestión de calidad farmacéutica.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"Calidad Línea del Tiempo Historia de la Calidad su evolución Timeline History of Quality","url":"https://www.youtube.com/watch?v=G9KdU1iHgNc"},{"cita":"Quality Gurus Explained: Deming, Juran, Crosby and Others","url":"https://www.youtube.com/watch?v=ZpOraNGnh6E"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente evolución histórica de la calidad: de la inspección a la gestión total en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de evolución histórica de la calidad: de la inspección a la gestión total"}],"keywords":["curso","gestión","calidad","farmacéutica","evolución","histórica","inspección","total","unidad","fundamentos"],"mapa":{"centro":"Evolución histórica de la calidad: de la inspección a la gestión total","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 1. Fundamentos de la gestión de calidad farmacéutica","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se aplica: Diagnóstico de un laboratorio con los siete principios","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y lista las siete situaciones observadas.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Relaciona cada situación con el principio o los principios de ISO 9000 que no se están aplicando y explica por qué.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Valora la madurez del laboratorio en cada principio con una escala de 1 a 4 que tú definas por escrito.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Identifica qué situaciones afectan más al paciente y cuáles al cumplimiento de las BPM.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Propón tres mejoras prioritarias, cada una con un indicador y un responsable.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Redacta una conclusión de media página para la gerencia.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Evolución histórica de la calidad: de la inspección a la gestión total","contexto":"En una planta o un laboratorio farmacéutico colombiano, el equipo analiza este caso de unidad 1. Fundamentos de la gestión de calidad farmacéutica: Laboratorio Andino de Genéricos (ficticio), de Bogotá, tiene 120 empleados y certificado de BPM. En una semana de observación se encontró (datos simulados): las decisiones de compra se toman por el precio sin evaluar proveedores; producción, control de calidad y bodega trabajan como islas y se culpan mutuamente de los retrasos; el personal no conoce la política de calidad, colgada en la recepción; los indicadores se calculan, pero nadie los analiza; las quejas subieron 40 % y se responden una a una sin buscar causas comunes; el gerente decide las prioridades «por experiencia»; y no hay un plan de mejora desde hace dos años. La pregunta que decide esta clase es: ¿Qué distingue el aseguramiento de la calidad de la etapa de inspección en la evolución histórica de la calidad?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"La inspección es más moderna porque usa equipos automáticos de medición en la línea de producción.","correcta":false,"retro":"La inspección es la etapa más antigua; la automatización no cambia su lógica de detectar al final."},{"texto":"El aseguramiento previene defectos con procesos planificados; la inspección los detecta al final.","correcta":true,"retro":"Correcto. El paso de detectar a prevenir es el cambio de fondo entre ambas etapas."},{"texto":"El aseguramiento consiste en inspeccionar el ciento por ciento de las unidades antes de liberarlas.","correcta":false,"retro":"Inspeccionar todo sigue siendo inspección; el aseguramiento actúa sobre el proceso, no solo sobre el producto."},{"texto":"No hay diferencia de fondo: ambos se basan en revisar el producto terminado al final del proceso.","correcta":false,"retro":"Sí la hay: el aseguramiento construye la calidad en el proceso, antes de que el producto exista."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 03. Aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica$t$
     AND m.title = $u$Unidad 1. Fundamentos de la gestión de calidad farmacéutica$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica$t$, $u$Unidad 1. Fundamentos de la gestión de calidad farmacéutica$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica","texto":"En una planta o un laboratorio farmacéutico colombiano, un lote cumple las especificaciones, pero la revisión del expediente muestra una etapa sin verificar. Lo que está en juego es el criterio de aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica con tus propias palabras y reconocer por qué importa en curso de Gestión de Calidad Farmacéutica.","Relacionar aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica con unidad 1. Fundamentos de la gestión de calidad farmacéutica y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Interpreta el ciclo PHVA, la trilogía de Juran y el concepto de cero defectos y su aplicación en un laboratorio o servicio farmacéutico."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica aparece en medio de una decisión que no admite improvisación: un lote cumple las especificaciones, pero la revisión del expediente muestra una etapa sin verificar. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de la gestión de calidad farmacéutica. El objetivo del curso es claro: Que el Químico Farmacéutico sea capaz de diseñar, implementar, medir y mejorar un sistema de gestión de calidad en una organización farmacéutica colombiana, integrando ICH Q10, ISO 9001:2015 y la normativa del INVIMA y MinSalud. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Interpreta el ciclo PHVA, la trilogía de Juran y el concepto de cero defectos y su aplicación en un laboratorio o servicio farmacéutico.","Una pregunta que se usa para comprobar esta clase es: «En un servicio farmacéutico suben los errores de dispensación. El equipo analiza causas, prueba un doble chequeo en un turno, mide los errores durante un mes y, como bajan, lo adopta en todos los turnos. ¿A qué fase del PHVA corresponde medir los errores durante el mes?» La respuesta correcta se apoya en lo siguiente: En el ciclo de Deming se planea (causas y cambio), se hace (prueba a pequeña escala), se verifica (se miden y comparan los resultados) y se actúa (se estandariza o se ajusta). La fuente citada es: Ciclo PHVA (Deming); ISO 9001:2015, introducción (0.3.2).. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos de la gestión de calidad farmacéutica y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Diagnóstico de madurez con los siete principios y plan de mejoras prioritarias.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y lista las siete situaciones observadas. Evidencia que debe quedar: Registro del paso.","Relaciona cada situación con el principio o los principios de ISO 9000 que no se están aplicando y explica por qué. Evidencia que debe quedar: Registro del paso.","Valora la madurez del laboratorio en cada principio con una escala de 1 a 4 que tú definas por escrito. Evidencia que debe quedar: Registro del paso.","Identifica qué situaciones afectan más al paciente y cuáles al cumplimiento de las BPM. Evidencia que debe quedar: Registro del paso.","Propón tres mejoras prioritarias, cada una con un indicador y un responsable. Evidencia que debe quedar: Registro del paso.","Redacta una conclusión de media página para la gerencia. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confundir el análisis final con la garantía de calidad Corrección: el muestreo no detecta todos los defectos; la calidad se construye durante el proceso.","Error: tratar todos los riesgos como iguales Corrección: priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto.","Error: copiar un procedimiento de otra planta Corrección: el procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica»?","respuesta":"Interpreta el ciclo PHVA, la trilogía de Juran y el concepto de cero defectos y su aplicación en un laboratorio o servicio farmacéutico."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Diagnóstico de madurez con los siete principios y plan de mejoras prioritarias.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de la gestión de calidad farmacéutica.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"W. EDWARDS DEMING creador del modelo del círculo de la calidad y la mejora contínua PHVA","url":"https://www.youtube.com/watch?v=N3Vjggq51xI"},{"cita":"Los principios de Calidad Joseph M. Juran ¿Quién fue? su trilogía, frases y aportaciones","url":"https://www.youtube.com/watch?v=LYmicHDGtzw"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica"}],"keywords":["curso","gestión","calidad","farmacéutica","aportes","deming","juran","crosby","unidad","fundamentos"],"mapa":{"centro":"Aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 1. Fundamentos de la gestión de calidad farmacéutica","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se aplica: Diagnóstico de un laboratorio con los siete principios","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y lista las siete situaciones observadas.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Relaciona cada situación con el principio o los principios de ISO 9000 que no se están aplicando y explica por qué.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Valora la madurez del laboratorio en cada principio con una escala de 1 a 4 que tú definas por escrito.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Identifica qué situaciones afectan más al paciente y cuáles al cumplimiento de las BPM.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Propón tres mejoras prioritarias, cada una con un indicador y un responsable.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Redacta una conclusión de media página para la gerencia.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica","contexto":"En una planta o un laboratorio farmacéutico colombiano, el equipo analiza este caso de unidad 1. Fundamentos de la gestión de calidad farmacéutica: Laboratorio Andino de Genéricos (ficticio), de Bogotá, tiene 120 empleados y certificado de BPM. En una semana de observación se encontró (datos simulados): las decisiones de compra se toman por el precio sin evaluar proveedores; producción, control de calidad y bodega trabajan como islas y se culpan mutuamente de los retrasos; el personal no conoce la política de calidad, colgada en la recepción; los indicadores se calculan, pero nadie los analiza; las quejas subieron 40 % y se responden una a una sin buscar causas comunes; el gerente decide las prioridades «por experiencia»; y no hay un plan de mejora desde hace dos años. La pregunta que decide esta clase es: En un servicio farmacéutico suben los errores de dispensación. El equipo analiza causas, prueba un doble chequeo en un turno, mide los errores durante un mes y, como bajan, lo adopta en todos los turnos. ¿A qué fase del PHVA corresponde medir los errores durante el mes?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"A Planear, porque medir sirve para fijar la meta del proyecto de mejora antes de actuar.","correcta":false,"retro":"La meta se fija antes de probar el cambio; aquí la medición evalúa lo que ya se probó."},{"texto":"A Hacer, porque la medición ocurre al mismo tiempo que se prueba el doble chequeo en el turno.","correcta":false,"retro":"Hacer es ejecutar el cambio a pequeña escala; comparar sus resultados con lo esperado es otra fase."},{"texto":"A Actuar, porque los datos del mes llevan a la decisión de extender el cambio a todos los turnos.","correcta":false,"retro":"Actuar es estandarizar o ajustar a partir de lo verificado; la medición la precede."},{"texto":"A Verificar, porque compara los resultados de la prueba con lo que se esperaba lograr.","correcta":true,"retro":"Correcto. Verificar es medir y comparar antes de decidir si se estandariza."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
