    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 16. Habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad$t$
     AND m.title = $u$Unidad 3. Modelos de sistema de gestión de calidad: ICH Q10 e ISO 9001:2015$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad$t$, $u$Unidad 3. Modelos de sistema de gestión de calidad: ICH Q10 e ISO 9001:2015$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad","texto":"En una planta o un laboratorio farmacéutico colombiano, un proveedor cambia de planta y el certificado que llega no cubre la línea que fabrica el insumo. Lo que está en juego es el criterio de habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad con tus propias palabras y reconocer por qué importa en curso de Gestión de Calidad Farmacéutica.","Relacionar habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad con unidad 3. Modelos de sistema de gestión de calidad: ICH Q10 e ISO 9001:2015 y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Comprende cómo la gestión del conocimiento y la gestión de riesgos (ICH Q9) sostienen las decisiones del sistema de calidad."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad aparece en medio de una decisión que no admite improvisación: un proveedor cambia de planta y el certificado que llega no cubre la línea que fabrica el insumo. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 3. Modelos de sistema de gestión de calidad: ICH Q10 e ISO 9001:2015. El objetivo del curso es claro: Que el Químico Farmacéutico sea capaz de diseñar, implementar, medir y mejorar un sistema de gestión de calidad en una organización farmacéutica colombiana, integrando ICH Q10, ISO 9001:2015 y la normativa del INVIMA y MinSalud. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Comprende cómo la gestión del conocimiento y la gestión de riesgos (ICH Q9) sostienen las decisiones del sistema de calidad.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en requisito y en evidencia documentada, no en la intuición.","La clase pertenece a unidad 3. Modelos de sistema de gestión de calidad: ICH Q10 e ISO 9001:2015 y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Definir el requisito. Identifica la norma, el procedimiento o la especificación aplicable y escribe el criterio antes de mirar el dato. Evidencia que debe quedar: Requisito citado por su nombre.","Reunir la evidencia. Localiza registros, resultados, certificados y firmas que correspondan al caso concreto, no a un lote parecido. Evidencia que debe quedar: Expediente del caso.","Comparar contra el criterio. Evalúa la evidencia con el criterio definido; separa lo que cumple de lo que no y documenta las diferencias. Evidencia que debe quedar: Lista de verificación.","Evaluar el impacto. Decide si la diferencia afecta la seguridad, la eficacia, la calidad o la validez del dato, y a qué lotes alcanza. Evidencia que debe quedar: Evaluación de impacto.","Actuar y verificar. Corrige, previene, asigna responsable y fecha, y comprueba con evidencia que la acción funcionó. Evidencia que debe quedar: CAPA cerrada y verificada.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: La política de calidad de Laboratorios Pacífico (ficticio) dice: «Somos líderes en calidad y nos comprometemos con la excelencia y la satisfacción total de nuestros clientes». Sus objetivos son «mejorar la calidad» y «aumentar la satisfacción». En una auditoría, ningún operario supo explicar qué significaban en su trabajo y la gerencia no los había revisado en tres años (datos simulados). No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: documentar después de ejecutar Corrección: el registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad.","Error: copiar un procedimiento de otra planta Corrección: el procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso.","Error: confundir el análisis final con la garantía de calidad Corrección: el muestreo no detecta todos los defectos; la calidad se construye durante el proceso.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad»?","respuesta":"Comprende cómo la gestión del conocimiento y la gestión de riesgos (ICH Q9) sostienen las decisiones del sistema de calidad."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 3. Modelos de sistema de gestión de calidad: ICH Q10 e ISO 9001:2015.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"ISPE Good Practice Guide: Knowledge Management in the Pharmaceutical Industry","url":"https://www.youtube.com/watch?v=oaZS5p_tXfE"},{"cita":"ICH guideline Q9 on quality risk management. TGA Australia / ICH (EN)","url":"https://tga.gov.au/sites/default/files/2024-12/ich_guideline_q9_on_quality_risk_management.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad"}],"keywords":["curso","gestión","calidad","farmacéutica","habilitadores","conocimiento","riesgos","unidad","modelos","sistema"],"mapa":{"centro":"Habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 3. Modelos de sistema de gestión de calidad: ICH Q10 e ISO 9001:2015","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Definir el requisito","Reunir la evidencia","Comparar contra el criterio"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Requisito citado por su nombre","Expediente del caso","Lista de verificación"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se sostiene una decisión de calidad","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Definir el requisito","detalle":"Identifica la norma, el procedimiento o la especificación aplicable y escribe el criterio antes de mirar el dato.","icono":"Search","evidencia":"Requisito citado por su nombre"},{"titulo":"Reunir la evidencia","detalle":"Localiza registros, resultados, certificados y firmas que correspondan al caso concreto, no a un lote parecido.","icono":"ClipboardList","evidencia":"Expediente del caso"},{"titulo":"Comparar contra el criterio","detalle":"Evalúa la evidencia con el criterio definido; separa lo que cumple de lo que no y documenta las diferencias.","icono":"Workflow","evidencia":"Lista de verificación"},{"titulo":"Evaluar el impacto","detalle":"Decide si la diferencia afecta la seguridad, la eficacia, la calidad o la validez del dato, y a qué lotes alcanza.","icono":"FileCheck","evidencia":"Evaluación de impacto"},{"titulo":"Actuar y verificar","detalle":"Corrige, previene, asigna responsable y fecha, y comprueba con evidencia que la acción funcionó.","icono":"RefreshCw","evidencia":"CAPA cerrada y verificada"}]},"caso":{"titulo":"Habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad","contexto":"La política de calidad de Laboratorios Pacífico (ficticio) dice: «Somos líderes en calidad y nos comprometemos con la excelencia y la satisfacción total de nuestros clientes». Sus objetivos son «mejorar la calidad» y «aumentar la satisfacción». En una auditoría, ningún operario supo explicar qué significaban en su trabajo y la gerencia no los había revisado en tres años (datos simulados).","pregunta":"¿Qué decisión demuestra que entendiste habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 17. Los cuatro elementos del PQS y su equivalente en las BPM europeas/PIC/S
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Los cuatro elementos del PQS y su equivalente en las BPM europeas/PIC/S$t$
     AND m.title = $u$Unidad 3. Modelos de sistema de gestión de calidad: ICH Q10 e ISO 9001:2015$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Los cuatro elementos del PQS y su equivalente en las BPM europeas/PIC/S$t$, $u$Unidad 3. Modelos de sistema de gestión de calidad: ICH Q10 e ISO 9001:2015$u$;
