  -- 23. Enfoque basado en procesos: entradas, salidas, interacciones y dueños
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Enfoque basado en procesos: entradas, salidas, interacciones y dueños$t$
     AND m.title = $u$Unidad 4. Enfoque por procesos, indicadores y revisión por la dirección$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Enfoque basado en procesos: entradas, salidas, interacciones y dueños$t$, $u$Unidad 4. Enfoque por procesos, indicadores y revisión por la dirección$u$;
