  -- 24. Mapa de procesos y caracterización de procesos de un laboratorio farmacéutico
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Mapa de procesos y caracterización de procesos de un laboratorio farmacéutico$t$
     AND m.title = $u$Unidad 4. Enfoque por procesos, indicadores y revisión por la dirección$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Mapa de procesos y caracterización de procesos de un laboratorio farmacéutico$t$, $u$Unidad 4. Enfoque por procesos, indicadores y revisión por la dirección$u$;
