  -- 09. Responsabilidades del Químico Farmacéutico en QA y dirección técnica
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
