       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 13. Tratamiento de desviaciones durante la revisión del lote
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Tratamiento de desviaciones durante la revisión del lote$t$
     AND m.title = $u$Unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Tratamiento de desviaciones durante la revisión del lote$t$, $u$Unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Tratamiento de desviaciones durante la revisión del lote","texto":"En una planta o un laboratorio farmacéutico colombiano, un proveedor cambia de planta y el certificado que llega no cubre la línea que fabrica el insumo. Lo que está en juego es el criterio de tratamiento de desviaciones durante la revisión del lote. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar tratamiento de desviaciones durante la revisión del lote con tus propias palabras y reconocer por qué importa en curso de Aseguramiento de la Calidad Farmacéutica.","Relacionar tratamiento de desviaciones durante la revisión del lote con unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar tratamiento de desviaciones durante la revisión del lote y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Aplica criterios para decidir sobre la disposición de un lote cuando la revisión revela desviaciones reportadas o no reportadas. Al finalizar esta clase el estudiante podrá decidir, desde la función de Aseguramiento de Calidad, cómo tratar las desviaciones detectadas durante la revisión del registro de lote antes de emitir la disposición del lote (aprobado, rechazado o en cuarentena extendida). La revisión del registro de lote no es una lectura de verificación de firmas; es el último filtro documental antes de que un medicamento llegue al paciente.…"},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, tratamiento de desviaciones durante la revisión del lote aparece en medio de una decisión que no admite improvisación: un proveedor cambia de planta y el certificado que llega no cubre la línea que fabrica el insumo. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto. El objetivo del curso es claro: Que el Químico Farmacéutico comprenda y aplique los procesos de Aseguramiento de la Calidad necesarios para garantizar que cada lote liberado cumpla los requisitos de calidad, seguridad y eficacia, conforme a la normativa colombiana (Decreto 677/1995, Resolución 1160/2016 y regulación INVIMA de vigilancia) y a los referentes OMS, PIC/S e ICH. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Aplica criterios para decidir sobre la disposición de un lote cuando la revisión revela desviaciones reportadas o no reportadas. Al finalizar esta clase el estudiante podrá decidir, desde la función de Aseguramiento de Calidad, cómo tratar las desviaciones detectadas durante la revisión del registro de lote antes de emitir la disposición del lote (aprobado, rechazado o en cuarentena extendida). La revisión del registro de lote no es una lectura de verificación de firmas; es el último filtro documental antes de que un medicamento llegue al paciente.…","Una pregunta que se usa para comprobar esta clase es: «Al revisar un registro de lote, QA encuentra que la temperatura de secado estuvo 8 °C por encima del rango durante 20 minutos y nadie abrió una desviación. Los resultados analíticos cumplen. ¿Qué análisis es correcto?» La respuesta correcta se apoya en lo siguiente: Una desviación no reportada se gestiona como cualquier desviación: se documenta, se investiga la causa (incluido por qué no se reportó), se evalúa el impacto en la calidad (por ejemplo, degradación o estabilidad) y se decide la disposición del lote con esa evidencia. La fuente citada es: OMS TRS 986, anexo 2, desviaciones y revisión de registros; ICH Q10, CAPA.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de revisión del registro de lote con decisión de disposición.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar tratamiento de desviaciones durante la revisión del lote, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y arma una lista de verificación de revisión de registro de lote (pesadas, controles en proceso, conciliaciones, desviaciones, resultados y firmas). Evidencia que debe quedar: Registro del paso.","Aplica la lista al lote y registra cada hallazgo. Evidencia que debe quedar: Registro del paso.","Clasifica cada hallazgo (crítico, mayor o menor) y explica el riesgo que representa. Evidencia que debe quedar: Registro del paso.","Indica qué investigación o corrección exige cada hallazgo antes de decidir. Evidencia que debe quedar: Registro del paso.","Decide la disposición del lote: liberar, retener o rechazar, con su justificación. Evidencia que debe quedar: Registro del paso.","Redacta la comunicación al área comercial sobre el pedido urgente. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: cerrar una CAPA sin verificar eficacia Corrección: una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato.","Error: tratar todos los riesgos como iguales Corrección: priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto.","Error: documentar después de ejecutar Corrección: el registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar tratamiento de desviaciones durante la revisión del lote en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Tratamiento de desviaciones durante la revisión del lote»?","respuesta":"Aplica criterios para decidir sobre la disposición de un lote cuando la revisión revela desviaciones reportadas o no reportadas. Al finalizar esta clase el estudiante podrá decidir, desde la función de Aseguramiento de Calidad, cómo tratar las desviaciones detectadas durante la revisión del registro de lote antes de emitir la disposición del lote (aprobado, rechazado o en cuarentena extendida). La revisión del registro de lote no es una lectura de verificación de firmas; es el último filtro documental antes de que un medicamento llegue al paciente.…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de revisión del registro de lote con decisión de disposición.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Tratamiento de desviaciones durante la revisión del lote se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"Guía de inspección BPM – Desviaciones (DIGEMID, Perú)","url":"https://www.youtube.com/watch?v=lxB9J8-NVzQ"},{"cita":"[Página web] Resolución 1160 de 2016 (Manuales de BPM e inspección). MinSalud / Normograma INVIMA (ES)","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente tratamiento de desviaciones durante la revisión del lote en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de tratamiento de desviaciones durante la revisión del lote"}],"keywords":["curso","aseguramiento","calidad","farmacéutica","tratamiento","desviaciones","durante","revisión","unidad","liberación","lotes","registros"],"mapa":{"centro":"Tratamiento de desviaciones durante la revisión del lote","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se aplica: Revisión de un registro de lote y decisión de liberación","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y arma una lista de verificación de revisión de registro de lote (pesadas, controles en proceso, conciliaciones, desviaciones, resultados y firmas).","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Aplica la lista al lote y registra cada hallazgo.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Clasifica cada hallazgo (crítico, mayor o menor) y explica el riesgo que representa.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Indica qué investigación o corrección exige cada hallazgo antes de decidir.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Decide la disposición del lote: liberar, retener o rechazar, con su justificación.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Redacta la comunicación al área comercial sobre el pedido urgente.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Tratamiento de desviaciones durante la revisión del lote","contexto":"En una planta o un laboratorio farmacéutico colombiano, el equipo analiza este caso de unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto: Te llega para liberación el lote 25-118 de tabletas de un antihipertensivo de Laboratorios Ceiba (ficticio). En la revisión encuentras (datos simulados): la firma del verificador falta en la pesada de un excipiente; un control de dureza fuera de rango a las 10:40 aparece corregido con corrector líquido, sin explicación; la conciliación de blísteres impresos tiene 120 unidades sin explicar; hay una desviación abierta por una parada de la tableteadora de 40 minutos, con su investigación sin terminar; los resultados analíticos de control de calidad cumplen todas las especificaciones; y el lote tiene un pedido urgente de un distribuidor. La pregunta que decide esta clase es: Al revisar un registro de lote, QA encuentra que la temperatura de secado estuvo 8 °C por encima del rango durante 20 minutos y nadie abrió una desviación. Los resultados analíticos cumplen. ¿Qué análisis es correcto?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Hay una desviación no reportada: se abre, se evalúa su impacto en la calidad y se decide el lote con esa evidencia.","correcta":true,"retro":"Correcto. Los resultados conformes son una evidencia, no reemplazan la evaluación del impacto."},{"texto":"Como los resultados cumplen, basta con anotar el dato en el registro y liberar el lote sin ningún otro trámite adicional.","correcta":false,"retro":"Anotarlo sin evaluar el impacto oculta una desviación y su posible efecto en la estabilidad."},{"texto":"Se libera el lote y se sanciona al operario que no reportó la desviación durante el proceso.","correcta":false,"retro":"La sanción no resuelve la evaluación del lote ni la causa del no reporte."},{"texto":"El lote se rechaza siempre, porque toda desviación en un parámetro crítico obliga a destruirlo.","correcta":false,"retro":"No hay rechazo automático: la decisión se basa en la evaluación del impacto."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 14. Objetivo y contenido de la Revisión Anual de Producto
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Objetivo y contenido de la Revisión Anual de Producto$t$
     AND m.title = $u$Unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Objetivo y contenido de la Revisión Anual de Producto$t$, $u$Unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Objetivo y contenido de la Revisión Anual de Producto","texto":"En una planta o un laboratorio farmacéutico colombiano, un indicador empeora durante tres meses y nadie sabe explicar por qué. Lo que está en juego es el criterio de objetivo y contenido de la Revisión Anual de Producto. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar objetivo y contenido de la Revisión Anual de Producto con tus propias palabras y reconocer por qué importa en curso de Aseguramiento de la Calidad Farmacéutica.","Relacionar objetivo y contenido de la Revisión Anual de Producto con unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar objetivo y contenido de la Revisión Anual de Producto y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Describe el propósito de la RAP/PQR y los elementos que debe incluir: lotes, desviaciones, cambios, quejas, estabilidad y devoluciones."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, objetivo y contenido de la Revisión Anual de Producto aparece en medio de una decisión que no admite improvisación: un indicador empeora durante tres meses y nadie sabe explicar por qué. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto. El objetivo del curso es claro: Que el Químico Farmacéutico comprenda y aplique los procesos de Aseguramiento de la Calidad necesarios para garantizar que cada lote liberado cumpla los requisitos de calidad, seguridad y eficacia, conforme a la normativa colombiana (Decreto 677/1995, Resolución 1160/2016 y regulación INVIMA de vigilancia) y a los referentes OMS, PIC/S e ICH. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Describe el propósito de la RAP/PQR y los elementos que debe incluir: lotes, desviaciones, cambios, quejas, estabilidad y devoluciones.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en requisito y en evidencia documentada, no en la intuición.","La clase pertenece a unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de revisión del registro de lote con decisión de disposición.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar objetivo y contenido de la Revisión Anual de Producto, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y arma una lista de verificación de revisión de registro de lote (pesadas, controles en proceso, conciliaciones, desviaciones, resultados y firmas). Evidencia que debe quedar: Registro del paso.","Aplica la lista al lote y registra cada hallazgo. Evidencia que debe quedar: Registro del paso.","Clasifica cada hallazgo (crítico, mayor o menor) y explica el riesgo que representa. Evidencia que debe quedar: Registro del paso.","Indica qué investigación o corrección exige cada hallazgo antes de decidir. Evidencia que debe quedar: Registro del paso.","Decide la disposición del lote: liberar, retener o rechazar, con su justificación. Evidencia que debe quedar: Registro del paso.","Redacta la comunicación al área comercial sobre el pedido urgente. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: copiar un procedimiento de otra planta Corrección: el procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso.","Error: confundir el análisis final con la garantía de calidad Corrección: el muestreo no detecta todos los defectos; la calidad se construye durante el proceso.","Error: tratar todos los riesgos como iguales Corrección: priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar objetivo y contenido de la Revisión Anual de Producto en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Objetivo y contenido de la Revisión Anual de Producto»?","respuesta":"Describe el propósito de la RAP/PQR y los elementos que debe incluir: lotes, desviaciones, cambios, quejas, estabilidad y devoluciones."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de revisión del registro de lote con decisión de disposición.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Objetivo y contenido de la Revisión Anual de Producto se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"Revisión Anual del Producto (RAP)","url":"https://www.youtube.com/watch?v=90T40JgzPBI"},{"cita":"Cápsula del conocimiento \"Revisión Anual de Producto\"","url":"https://www.youtube.com/watch?v=TCDtSyp2PyU"},{"cita":"[Página web] Revisión de la calidad del producto (PQR): evidencia, tendencias y decisiones que mejoran el próximo lote. SG Systems Global (ES)","url":"https://sgsystemsglobal.com/es/glosario/Revisi%C3%B3n-de-la-calidad-del-producto-pqr/"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente objetivo y contenido de la Revisión Anual de Producto en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de objetivo y contenido de la Revisión Anual de Producto"}],"keywords":["curso","aseguramiento","calidad","farmacéutica","objetivo","contenido","revisión","anual","producto","unidad","liberación","lotes"],"mapa":{"centro":"Objetivo y contenido de la Revisión Anual de Producto","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se aplica: Revisión de un registro de lote y decisión de liberación","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y arma una lista de verificación de revisión de registro de lote (pesadas, controles en proceso, conciliaciones, desviaciones, resultados y firmas).","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Aplica la lista al lote y registra cada hallazgo.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Clasifica cada hallazgo (crítico, mayor o menor) y explica el riesgo que representa.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Indica qué investigación o corrección exige cada hallazgo antes de decidir.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Decide la disposición del lote: liberar, retener o rechazar, con su justificación.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Redacta la comunicación al área comercial sobre el pedido urgente.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Revisión de un registro de lote y decisión de liberación","contexto":"Te llega para liberación el lote 25-118 de tabletas de un antihipertensivo de Laboratorios Ceiba (ficticio). En la revisión encuentras (datos simulados): la firma del verificador falta en la pesada de un excipiente; un control de dureza fuera de rango a las 10:40 aparece corregido con corrector líquido, sin explicación; la conciliación de blísteres impresos tiene 120 unidades sin explicar; hay una desviación abierta por una parada de la tableteadora de 40 minutos, con su investigación sin terminar; los resultados analíticos de control de calidad cumplen todas las especificaciones; y el lote tiene un pedido urgente de un distribuidor.","pregunta":"¿Qué decisión demuestra que entendiste objetivo y contenido de la Revisión Anual de Producto?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 15. Elaboración de la RAP y análisis de tendencias
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Elaboración de la RAP y análisis de tendencias$t$
     AND m.title = $u$Unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Elaboración de la RAP y análisis de tendencias$t$, $u$Unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Elaboración de la RAP y análisis de tendencias","texto":"En una planta o un laboratorio farmacéutico colombiano, una acción correctiva se cerró, pero el mismo problema reaparece en el lote siguiente. Lo que está en juego es el criterio de elaboración de la RAP y análisis de tendencias. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar elaboración de la RAP y análisis de tendencias con tus propias palabras y reconocer por qué importa en curso de Aseguramiento de la Calidad Farmacéutica.","Relacionar elaboración de la RAP y análisis de tendencias con unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar elaboración de la RAP y análisis de tendencias y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Aplica herramientas básicas de análisis de tendencias a los datos del año y redacta conclusiones y acciones de la RAP."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, elaboración de la RAP y análisis de tendencias aparece en medio de una decisión que no admite improvisación: una acción correctiva se cerró, pero el mismo problema reaparece en el lote siguiente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto. El objetivo del curso es claro: Que el Químico Farmacéutico comprenda y aplique los procesos de Aseguramiento de la Calidad necesarios para garantizar que cada lote liberado cumpla los requisitos de calidad, seguridad y eficacia, conforme a la normativa colombiana (Decreto 677/1995, Resolución 1160/2016 y regulación INVIMA de vigilancia) y a los referentes OMS, PIC/S e ICH. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Aplica herramientas básicas de análisis de tendencias a los datos del año y redacta conclusiones y acciones de la RAP.","Una pregunta que se usa para comprobar esta clase es: «La revisión anual de un producto concluye «producto satisfactorio» después de listar los 24 lotes del año, sin tendencias ni conclusiones sobre desviaciones, quejas o estabilidad. ¿Cuál es la valoración más acertada?» La respuesta correcta se apoya en lo siguiente: La revisión periódica de calidad del producto analiza materias primas, controles en proceso, resultados, desviaciones, cambios, estabilidad, quejas, devoluciones, retiros y la eficacia de las acciones previas, para confirmar la consistencia del proceso y proponer mejoras. La fuente citada es: OMS TRS 986, anexo 2, revisión de la calidad del producto.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de revisión del registro de lote con decisión de disposición.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar elaboración de la RAP y análisis de tendencias, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y arma una lista de verificación de revisión de registro de lote (pesadas, controles en proceso, conciliaciones, desviaciones, resultados y firmas). Evidencia que debe quedar: Registro del paso.","Aplica la lista al lote y registra cada hallazgo. Evidencia que debe quedar: Registro del paso.","Clasifica cada hallazgo (crítico, mayor o menor) y explica el riesgo que representa. Evidencia que debe quedar: Registro del paso.","Indica qué investigación o corrección exige cada hallazgo antes de decidir. Evidencia que debe quedar: Registro del paso.","Decide la disposición del lote: liberar, retener o rechazar, con su justificación. Evidencia que debe quedar: Registro del paso.","Redacta la comunicación al área comercial sobre el pedido urgente. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En una planta ficticia, las revisiones anuales de producto se entregan puntualmente cada año, pero nadie las discute. Al leer las de los últimos tres años de un comprimido, una analista nueva nota que el promedio de disolución bajó de 92 % a 84 % (la especificación es Q = 75 % a 30 minutos) y que cada informe concluyó «producto satisfactorio» (datos simulados). No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: copiar un procedimiento de otra planta Corrección: el procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso.","Error: documentar después de ejecutar Corrección: el registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad.","Error: tratar todos los riesgos como iguales Corrección: priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar elaboración de la RAP y análisis de tendencias en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Elaboración de la RAP y análisis de tendencias»?","respuesta":"Aplica herramientas básicas de análisis de tendencias a los datos del año y redacta conclusiones y acciones de la RAP."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de revisión del registro de lote con decisión de disposición.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Elaboración de la RAP y análisis de tendencias se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"Reporte de Revisión Anual de Producto - Apéndice B NOM-059","url":"https://www.youtube.com/watch?v=u87gKtGXRmc"},{"cita":"[Página web] How to conduct product quality review in pharmaceutical. GMPSOP (EN)","url":"https://www.gmpsop.com/product-quality-review-pharmaceutical-guide/"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente elaboración de la RAP y análisis de tendencias en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de elaboración de la RAP y análisis de tendencias"}],"keywords":["curso","aseguramiento","calidad","farmacéutica","elaboración","análisis","tendencias","unidad","liberación","lotes","revisión","registros"],"mapa":{"centro":"Elaboración de la RAP y análisis de tendencias","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se aplica: Revisión de un registro de lote y decisión de liberación","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y arma una lista de verificación de revisión de registro de lote (pesadas, controles en proceso, conciliaciones, desviaciones, resultados y firmas).","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Aplica la lista al lote y registra cada hallazgo.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Clasifica cada hallazgo (crítico, mayor o menor) y explica el riesgo que representa.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Indica qué investigación o corrección exige cada hallazgo antes de decidir.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Decide la disposición del lote: liberar, retener o rechazar, con su justificación.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Redacta la comunicación al área comercial sobre el pedido urgente.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Elaboración de la RAP y análisis de tendencias","contexto":"En una planta o un laboratorio farmacéutico colombiano, el equipo analiza este caso de unidad 2. Liberación de lotes, revisión de registros y Revisión Anual de Producto: Te llega para liberación el lote 25-118 de tabletas de un antihipertensivo de Laboratorios Ceiba (ficticio). En la revisión encuentras (datos simulados): la firma del verificador falta en la pesada de un excipiente; un control de dureza fuera de rango a las 10:40 aparece corregido con corrector líquido, sin explicación; la conciliación de blísteres impresos tiene 120 unidades sin explicar; hay una desviación abierta por una parada de la tableteadora de 40 minutos, con su investigación sin terminar; los resultados analíticos de control de calidad cumplen todas las especificaciones; y el lote tiene un pedido urgente de un distribuidor. La pregunta que decide esta clase es: La revisión anual de un producto concluye «producto satisfactorio» después de listar los 24 lotes del año, sin tendencias ni conclusiones sobre desviaciones, quejas o estabilidad. ¿Cuál es la valoración más acertada?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Es suficiente, porque la revisión anual solo exige demostrar que todos los lotes del año se liberaron.","correcta":false,"retro":"La revisión anual busca tendencias y mejoras, no solo confirmar liberaciones."},{"texto":"Es suficiente si la firma el director técnico y se archiva antes del cierre del año calendario.","correcta":false,"retro":"Las firmas no suplen el análisis que debe contener."},{"texto":"Es insuficiente: debe analizar las tendencias de todos sus elementos y proponer acciones.","correcta":true,"retro":"Correcto. Su valor está en el análisis y en las acciones que propone."},{"texto":"Es insuficiente solo porque debía incluir la información comercial de las ventas del producto.","correcta":false,"retro":"Las ventas no son un elemento de calidad de la revisión anual."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
