    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 32. Programa de farmacovigilancia del titular e interfaz con QA
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Programa de farmacovigilancia del titular e interfaz con QA$t$
     AND m.title = $u$Unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Programa de farmacovigilancia del titular e interfaz con QA$t$, $u$Unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Programa de farmacovigilancia del titular e interfaz con QA","texto":"En una planta o un laboratorio farmacéutico colombiano, un lote cumple las especificaciones, pero la revisión del expediente muestra una etapa sin verificar. Lo que está en juego es el criterio de programa de farmacovigilancia del titular e interfaz con QA. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar programa de farmacovigilancia del titular e interfaz con QA con tus propias palabras y reconocer por qué importa en curso de Aseguramiento de la Calidad Farmacéutica.","Relacionar programa de farmacovigilancia del titular e interfaz con QA con unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar programa de farmacovigilancia del titular e interfaz con QA y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Interpreta las obligaciones de farmacovigilancia del titular en Colombia y cómo se coordinan con quejas y desviaciones."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, programa de farmacovigilancia del titular e interfaz con QA aparece en medio de una decisión que no admite improvisación: un lote cumple las especificaciones, pero la revisión del expediente muestra una etapa sin verificar. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA. El objetivo del curso es claro: Que el Químico Farmacéutico comprenda y aplique los procesos de Aseguramiento de la Calidad necesarios para garantizar que cada lote liberado cumpla los requisitos de calidad, seguridad y eficacia, conforme a la normativa colombiana (Decreto 677/1995, Resolución 1160/2016 y regulación INVIMA de vigilancia) y a los referentes OMS, PIC/S e ICH. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Interpreta las obligaciones de farmacovigilancia del titular en Colombia y cómo se coordinan con quejas y desviaciones.","Una pregunta que se usa para comprobar esta clase es: «El titular de un registro conoce un evento adverso no serio, sin hospitalización, asociado a su medicamento. ¿En qué plazo debe comunicarlo al Invima según la norma vigente?» La respuesta correcta se apoya en lo siguiente: Desde el 1 de marzo de 2025, la Resolución 2024015321 de 2024 del Invima fija para los titulares 15 días calendario para los eventos serios y 90 para los no serios, contados desde el día siguiente al conocimiento, por eReporting Industria. La fuente citada es: Resolución 2024015321 de 2024 del Invima, artículo 8.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar programa de farmacovigilancia del titular e interfaz con QA, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Definir el requisito. Identifica la norma, el procedimiento o la especificación aplicable y escribe el criterio antes de mirar el dato. Evidencia que debe quedar: Requisito citado por su nombre.","Reunir la evidencia. Localiza registros, resultados, certificados y firmas que correspondan al caso concreto, no a un lote parecido. Evidencia que debe quedar: Expediente del caso.","Comparar contra el criterio. Evalúa la evidencia con el criterio definido; separa lo que cumple de lo que no y documenta las diferencias. Evidencia que debe quedar: Lista de verificación.","Evaluar el impacto. Decide si la diferencia afecta la seguridad, la eficacia, la calidad o la validez del dato, y a qué lotes alcanza. Evidencia que debe quedar: Evaluación de impacto.","Actuar y verificar. Corrige, previene, asigna responsable y fecha, y comprueba con evidencia que la acción funcionó. Evidencia que debe quedar: CAPA cerrada y verificada.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: Un laboratorio ficticio recibe en dos semanas: cuatro reportes de farmacovigilancia de crisis convulsivas en pacientes estables tratados con su levetiracetam, tres del mismo lote; una queja de una droguería por tabletas partidas en el blíster de ese lote; y la revisión del registro de lote muestra una desviación de dureza cerrada como «sin impacto» (datos simulados). No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confundir el análisis final con la garantía de calidad Corrección: el muestreo no detecta todos los defectos; la calidad se construye durante el proceso.","Error: cerrar una CAPA sin verificar eficacia Corrección: una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato.","Error: documentar después de ejecutar Corrección: el registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar programa de farmacovigilancia del titular e interfaz con QA en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Programa de farmacovigilancia del titular e interfaz con QA»?","respuesta":"Interpreta las obligaciones de farmacovigilancia del titular en Colombia y cómo se coordinan con quejas y desviaciones."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Programa de farmacovigilancia del titular e interfaz con QA se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"XII Encuentro Nacional de Farmacovigilancia","url":"https://www.youtube.com/watch?v=Fg6JbGuewv0"},{"cita":"Resolución 2004009455 de 2004 (INVIMA). INVIMA (ES)","url":"https://www.invima.gov.co/sites/default/files/resolucion_2004009455_2004.pdf"},{"cita":"[Página web] Vigilancia – Medicamentos y productos biológicos (farmacovigilancia, alertas, guías y formatos). INVIMA (ES)","url":"https://www.invima.gov.co/productos-vigilados/medicamentos-y-productos-biologicos/vigilancia-sqb"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente programa de farmacovigilancia del titular e interfaz con QA en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de programa de farmacovigilancia del titular e interfaz con QA"}],"keywords":["curso","aseguramiento","calidad","farmacéutica","programa","farmacovigilancia","titular","interfaz","unidad","tecnovigilancia","relación"],"mapa":{"centro":"Programa de farmacovigilancia del titular e interfaz con QA","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Definir el requisito","Reunir la evidencia","Comparar contra el criterio"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Requisito citado por su nombre","Expediente del caso","Lista de verificación"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se sostiene una decisión de calidad","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Definir el requisito","detalle":"Identifica la norma, el procedimiento o la especificación aplicable y escribe el criterio antes de mirar el dato.","icono":"Search","evidencia":"Requisito citado por su nombre"},{"titulo":"Reunir la evidencia","detalle":"Localiza registros, resultados, certificados y firmas que correspondan al caso concreto, no a un lote parecido.","icono":"ClipboardList","evidencia":"Expediente del caso"},{"titulo":"Comparar contra el criterio","detalle":"Evalúa la evidencia con el criterio definido; separa lo que cumple de lo que no y documenta las diferencias.","icono":"Workflow","evidencia":"Lista de verificación"},{"titulo":"Evaluar el impacto","detalle":"Decide si la diferencia afecta la seguridad, la eficacia, la calidad o la validez del dato, y a qué lotes alcanza.","icono":"FileCheck","evidencia":"Evaluación de impacto"},{"titulo":"Actuar y verificar","detalle":"Corrige, previene, asigna responsable y fecha, y comprueba con evidencia que la acción funcionó.","icono":"RefreshCw","evidencia":"CAPA cerrada y verificada"}]},"caso":{"titulo":"Programa de farmacovigilancia del titular e interfaz con QA","contexto":"En una planta o un laboratorio farmacéutico colombiano, el equipo analiza este caso de unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA: una situación que exige documentar la decisión. La pregunta que decide esta clase es: El titular de un registro conoce un evento adverso no serio, sin hospitalización, asociado a su medicamento. ¿En qué plazo debe comunicarlo al Invima según la norma vigente?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Dentro de las 72 horas siguientes, igual que todos los eventos, sin distinguir su gravedad.","correcta":false,"retro":"La norma vigente distingue por gravedad y no usa ese plazo para los titulares."},{"texto":"Solo si el médico tratante confirma por escrito la causalidad del evento con el medicamento.","correcta":false,"retro":"Se comunica la sospecha; la causalidad se evalúa después."},{"texto":"En la revisión anual de producto del medicamento, junto con las quejas del año.","correcta":false,"retro":"La revisión anual analiza, pero no es el canal de comunicación al Invima."},{"texto":"Dentro de los 90 días calendario siguientes a conocerlo, por eReporting Industria.","correcta":true,"retro":"Correcto. Los serios tienen 15 días calendario; los no serios, 90."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 33. Alertas sanitarias, señales y acciones de QA
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Alertas sanitarias, señales y acciones de QA$t$
     AND m.title = $u$Unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Alertas sanitarias, señales y acciones de QA$t$, $u$Unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA$u$;
