      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 35. Caso integrador: de la señal de seguridad al retiro del mercado
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso integrador: de la señal de seguridad al retiro del mercado$t$
     AND m.title = $u$Unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso integrador: de la señal de seguridad al retiro del mercado$t$, $u$Unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Caso integrador: de la señal de seguridad al retiro del mercado","texto":"En una planta o un laboratorio farmacéutico colombiano, un lote cumple las especificaciones, pero la revisión del expediente muestra una etapa sin verificar. Lo que está en juego es el criterio de caso integrador: de la señal de seguridad al retiro del mercado. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar caso integrador: de la señal de seguridad al retiro del mercado con tus propias palabras y reconocer por qué importa en curso de Aseguramiento de la Calidad Farmacéutica.","Relacionar caso integrador: de la señal de seguridad al retiro del mercado con unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar caso integrador: de la señal de seguridad al retiro del mercado y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Aplica de forma integrada revisión de lote, integridad de datos, quejas, recall y control de cambios en un caso colombiano. Aplicar de manera integrada los procesos de QA estudiados en el curso a un caso que va desde una señal de seguridad hasta la decisión de retiro de producto y el cierre con INVIMA. La farmacovigilancia y la tecnovigilancia generan información que QA no puede ignorar: un evento adverso o un incidente con un dispositivo puede ser la primera señal de un defecto de calidad.…"},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, caso integrador: de la señal de seguridad al retiro del mercado aparece en medio de una decisión que no admite improvisación: un lote cumple las especificaciones, pero la revisión del expediente muestra una etapa sin verificar. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA. El objetivo del curso es claro: Que el Químico Farmacéutico comprenda y aplique los procesos de Aseguramiento de la Calidad necesarios para garantizar que cada lote liberado cumpla los requisitos de calidad, seguridad y eficacia, conforme a la normativa colombiana (Decreto 677/1995, Resolución 1160/2016 y regulación INVIMA de vigilancia) y a los referentes OMS, PIC/S e ICH. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Aplica de forma integrada revisión de lote, integridad de datos, quejas, recall y control de cambios en un caso colombiano. Aplicar de manera integrada los procesos de QA estudiados en el curso a un caso que va desde una señal de seguridad hasta la decisión de retiro de producto y el cierre con INVIMA. La farmacovigilancia y la tecnovigilancia generan información que QA no puede ignorar: un evento adverso o un incidente con un dispositivo puede ser la primera señal de un defecto de calidad.…","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en requisito y en evidencia documentada, no en la intuición.","La clase pertenece a unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar caso integrador: de la señal de seguridad al retiro del mercado, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Definir el requisito. Identifica la norma, el procedimiento o la especificación aplicable y escribe el criterio antes de mirar el dato. Evidencia que debe quedar: Requisito citado por su nombre.","Reunir la evidencia. Localiza registros, resultados, certificados y firmas que correspondan al caso concreto, no a un lote parecido. Evidencia que debe quedar: Expediente del caso.","Comparar contra el criterio. Evalúa la evidencia con el criterio definido; separa lo que cumple de lo que no y documenta las diferencias. Evidencia que debe quedar: Lista de verificación.","Evaluar el impacto. Decide si la diferencia afecta la seguridad, la eficacia, la calidad o la validez del dato, y a qué lotes alcanza. Evidencia que debe quedar: Evaluación de impacto.","Actuar y verificar. Corrige, previene, asigna responsable y fecha, y comprueba con evidencia que la acción funcionó. Evidencia que debe quedar: CAPA cerrada y verificada.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: Un laboratorio ficticio recibe en dos semanas: cuatro reportes de farmacovigilancia de crisis convulsivas en pacientes estables tratados con su levetiracetam, tres del mismo lote; una queja de una droguería por tabletas partidas en el blíster de ese lote; y la revisión del registro de lote muestra una desviación de dureza cerrada como «sin impacto» (datos simulados). No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: cerrar una CAPA sin verificar eficacia Corrección: una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato.","Error: confundir el análisis final con la garantía de calidad Corrección: el muestreo no detecta todos los defectos; la calidad se construye durante el proceso.","Error: tratar todos los riesgos como iguales Corrección: priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar caso integrador: de la señal de seguridad al retiro del mercado en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Caso integrador: de la señal de seguridad al retiro del mercado»?","respuesta":"Aplica de forma integrada revisión de lote, integridad de datos, quejas, recall y control de cambios en un caso colombiano. Aplicar de manera integrada los procesos de QA estudiados en el curso a un caso que va desde una señal de seguridad hasta la decisión de retiro de producto y el cierre con INVIMA. La farmacovigilancia y la tecnovigilancia generan información que QA no puede ignorar: un evento adverso o un incidente con un dispositivo puede ser la primera señal de un defecto de calidad.…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Caso integrador: de la señal de seguridad al retiro del mercado se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"X Encuentro Nacional de Farmacovigilancia – Día 1","url":"https://www.youtube.com/watch?v=2FbcZA6nmG4"},{"cita":"Invima ordena retiro de Vitafer y otros potenciadores por químico no autorizado","url":"https://www.youtube.com/watch?v=855CYrFdaVk"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente caso integrador: de la señal de seguridad al retiro del mercado en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de caso integrador: de la señal de seguridad al retiro del mercado"}],"keywords":["curso","aseguramiento","calidad","farmacéutica","integrador","señal","seguridad","retiro","mercado","unidad","farmacovigilancia","tecnovigilancia"],"mapa":{"centro":"Caso integrador: de la señal de seguridad al retiro del mercado","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 5. Farmacovigilancia y tecnovigilancia en relación con QA","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Definir el requisito","Reunir la evidencia","Comparar contra el criterio"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Requisito citado por su nombre","Expediente del caso","Lista de verificación"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se sostiene una decisión de calidad","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Definir el requisito","detalle":"Identifica la norma, el procedimiento o la especificación aplicable y escribe el criterio antes de mirar el dato.","icono":"Search","evidencia":"Requisito citado por su nombre"},{"titulo":"Reunir la evidencia","detalle":"Localiza registros, resultados, certificados y firmas que correspondan al caso concreto, no a un lote parecido.","icono":"ClipboardList","evidencia":"Expediente del caso"},{"titulo":"Comparar contra el criterio","detalle":"Evalúa la evidencia con el criterio definido; separa lo que cumple de lo que no y documenta las diferencias.","icono":"Workflow","evidencia":"Lista de verificación"},{"titulo":"Evaluar el impacto","detalle":"Decide si la diferencia afecta la seguridad, la eficacia, la calidad o la validez del dato, y a qué lotes alcanza.","icono":"FileCheck","evidencia":"Evaluación de impacto"},{"titulo":"Actuar y verificar","detalle":"Corrige, previene, asigna responsable y fecha, y comprueba con evidencia que la acción funcionó.","icono":"RefreshCw","evidencia":"CAPA cerrada y verificada"}]},"caso":{"titulo":"Caso integrador: de la señal de seguridad al retiro del mercado","contexto":"Un laboratorio ficticio recibe en dos semanas: cuatro reportes de farmacovigilancia de crisis convulsivas en pacientes estables tratados con su levetiracetam, tres del mismo lote; una queja de una droguería por tabletas partidas en el blíster de ese lote; y la revisión del registro de lote muestra una desviación de dureza cerrada como «sin impacto» (datos simulados).","pregunta":"¿Qué decisión demuestra que entendiste caso integrador: de la señal de seguridad al retiro del mercado?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases completas con experiencia interactiva (catálogo).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;
  RAISE NOTICE 'Experiencias de %: % clases.', $t$Curso de Aseguramiento de la Calidad Farmacéutica$t$, v_n;
END $curso$;

-- ============================================================
--  Experiencias de clase: Curso de Buenas Prácticas de Laboratorio — BPL
--
--  Generado por scripts/generar-experiencias-catalogo.mjs a partir del
--  resumen de cada clase, los enlaces verificados y el material de
--  evaluación de contenido/aula/catalogo. No editar a mano.
--
--  35 clases. No toca cursos con experiencia escrita a
--  mano ni clases que ya tenían texto largo aprobado.
-- ============================================================

DO $curso$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Buenas Prácticas de Laboratorio — BPL$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Buenas Prácticas de Laboratorio — BPL$t$;
    RETURN;
  END IF;

  -- 01. Introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia?
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia?$t$
     AND m.title = $u$Unidad 1. Fundamentos y marco normativo de las BPL$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia?$t$, $u$Unidad 1. Fundamentos y marco normativo de las BPL$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia?","texto":"En una planta o un laboratorio farmacéutico colombiano, una acción correctiva se cerró, pero el mismo problema reaparece en el lote siguiente. Lo que está en juego es el criterio de introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia?. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia? con tus propias palabras y reconocer por qué importa en curso de Buenas Prácticas de Laboratorio — BPL.","Relacionar introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia? con unidad 1. Fundamentos y marco normativo de las BPL y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia? y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Comprende el propósito del curso, el papel de las BPL en la confiabilidad de los resultados analíticos y la ruta de aprendizaje hasta la certificación INVIMA."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia? aparece en medio de una decisión que no admite improvisación: una acción correctiva se cerró, pero el mismo problema reaparece en el lote siguiente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos y marco normativo de las BPL. El objetivo del curso es claro: Que el Químico Farmacéutico implemente, mantenga y demuestre ante el INVIMA y el ONAC el cumplimiento de las Buenas Prácticas de Laboratorio en un laboratorio de control de calidad farmacéutico, asegurando resultados analíticos confiables, trazables y seguros. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Comprende el propósito del curso, el papel de las BPL en la confiabilidad de los resultados analíticos y la ruta de aprendizaje hasta la certificación INVIMA.","Una pregunta que se usa para comprobar esta clase es: «El director de un laboratorio afirma que las BPL «son papeleo» y que lo importante es tener buenos equipos. ¿Cuál es la valoración más acertada?» La respuesta correcta se apoya en lo siguiente: La confiabilidad de un resultado depende del personal, los métodos validados, los equipos calificados, los materiales de referencia, los registros íntegros y la revisión independiente. Las BPL organizan todo eso. La fuente citada es: OMS TRS 957, anexo 1; Resolución 3619 de 2013.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos y marco normativo de las BPL y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe comparativo de marcos de calidad con recomendaciones.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia?, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y describe qué hace cada laboratorio. Evidencia que debe quedar: Registro del paso.","Compara cuatro marcos: BPL de control de calidad (Resolución 3619), BPL de la OCDE, ISO/IEC 17025 y BPM, por alcance, autoridad u organismo y obligatoriedad. Evidencia que debe quedar: Registro del paso.","Asigna a cada laboratorio el marco obligatorio y los voluntarios que le convendrían. Evidencia que debe quedar: Registro del paso.","Explica quién verifica cada marco (Invima, ONAC u otro) y con qué resultado (certificado o acreditación). Evidencia que debe quedar: Registro del paso.","Señala un error frecuente de interpretación para cada caso. Evidencia que debe quedar: Registro del paso.","Escribe una recomendación breve para cada consultante. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: tratar todos los riesgos como iguales Corrección: priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto.","Error: copiar un procedimiento de otra planta Corrección: el procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso.","Error: confundir el análisis final con la garantía de calidad Corrección: el muestreo no detecta todos los defectos; la calidad se construye durante el proceso.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia? en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia?»?","respuesta":"Comprende el propósito del curso, el papel de las BPL en la confiabilidad de los resultados analíticos y la ruta de aprendizaje hasta la certificación INVIMA."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe comparativo de marcos de calidad con recomendaciones.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia? se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos y marco normativo de las BPL.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"Buenas Prácticas de Laboratorio (BPL)","url":"https://www.youtube.com/watch?v=y4XAJrrk7js"},{"cita":"[Página web] OMS certifica en Buenas Prácticas al Laboratorio de Control de Calidad Farmacéutica del Invima. OPS/OMS (ES)","url":"https://www.paho.org/es/noticias/3-7-2020-oms-certifica-buenas-practicas-laboratorio-control-calidad-farmaceutica-invima"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia? en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia?"}],"keywords":["curso","buenas","prácticas","laboratorio","introducción","importan","colombia","unidad","fundamentos","marco","normativo"],"mapa":{"centro":"Introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia?","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 1. Fundamentos y marco normativo de las BPL","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se aplica: Marco de calidad para cuatro laboratorios","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y describe qué hace cada laboratorio.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Compara cuatro marcos: BPL de control de calidad (Resolución 3619), BPL de la OCDE, ISO/IEC 17025 y BPM, por alcance, autoridad u organismo y obligatoriedad.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Asigna a cada laboratorio el marco obligatorio y los voluntarios que le convendrían.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Explica quién verifica cada marco (Invima, ONAC u otro) y con qué resultado (certificado o acreditación).","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Señala un error frecuente de interpretación para cada caso.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Escribe una recomendación breve para cada consultante.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Introducción al curso: ¿qué son las BPL y por qué importan al QF en Colombia?","contexto":"En una planta o un laboratorio farmacéutico colombiano, el equipo analiza este caso de unidad 1. Fundamentos y marco normativo de las BPL: Una consultora ficticia recibe cuatro consultas (datos simulados): (1) el laboratorio de control de calidad interno de un fabricante de tabletas; (2) un laboratorio externo que analizará muestras de varios fabricantes; (3) un centro que hará estudios de toxicidad en animales para un dossier de una molécula nueva; (4) un laboratorio que calibra balanzas y termómetros para la industria. Cada uno pregunta qué marco de calidad debe cumplir, quién lo verifica y si es obligatorio u opcional. La pregunta que decide esta clase es: El director de un laboratorio afirma que las BPL «son papeleo» y que lo importante es tener buenos equipos. ¿Cuál es la valoración más acertada?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Es correcta: la exactitud de un resultado analítico depende solo del equipo de medición utilizado.","correcta":false,"retro":"El equipo es una parte; personal, método, materiales y registros también determinan el resultado."},{"texto":"Es errada: sin personal calificado, métodos validados, registros íntegros y revisión, un buen equipo no basta.","correcta":true,"retro":"Correcto. Las BPL convierten la medición en un resultado confiable y defendible."},{"texto":"Es correcta si los equipos tienen el certificado de calibración emitido por su propio fabricante.","correcta":false,"retro":"Un certificado no reemplaza el resto del sistema."},{"texto":"Es errada solo porque el Invima exige un número mínimo de procedimientos escritos en cada laboratorio de control.","correcta":false,"retro":"No se trata de un número de documentos, sino de la confiabilidad del resultado."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 02. Resolución 3619 de 2013: estructura y alcance
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Resolución 3619 de 2013: estructura y alcance$t$
     AND m.title = $u$Unidad 1. Fundamentos y marco normativo de las BPL$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Resolución 3619 de 2013: estructura y alcance$t$, $u$Unidad 1. Fundamentos y marco normativo de las BPL$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Resolución 3619 de 2013: estructura y alcance","texto":"En una planta o un laboratorio farmacéutico colombiano, una acción correctiva se cerró, pero el mismo problema reaparece en el lote siguiente. Lo que está en juego es el criterio de resolución 3619 de 2013: estructura y alcance. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar resolución 3619 de 2013: estructura y alcance con tus propias palabras y reconocer por qué importa en curso de Buenas Prácticas de Laboratorio — BPL.","Relacionar resolución 3619 de 2013: estructura y alcance con unidad 1. Fundamentos y marco normativo de las BPL y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar resolución 3619 de 2013: estructura y alcance y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Describe la estructura del Manual de BPL de control de calidad (Anexo 1) y la guía de evaluación (Anexo 2), y a quién aplica en Colombia."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, resolución 3619 de 2013: estructura y alcance aparece en medio de una decisión que no admite improvisación: una acción correctiva se cerró, pero el mismo problema reaparece en el lote siguiente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos y marco normativo de las BPL. El objetivo del curso es claro: Que el Químico Farmacéutico implemente, mantenga y demuestre ante el INVIMA y el ONAC el cumplimiento de las Buenas Prácticas de Laboratorio en un laboratorio de control de calidad farmacéutico, asegurando resultados analíticos confiables, trazables y seguros. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Describe la estructura del Manual de BPL de control de calidad (Anexo 1) y la guía de evaluación (Anexo 2), y a quién aplica en Colombia.","Una pregunta que se usa para comprobar esta clase es: «Un fabricante tiene su propio laboratorio de control dentro de la planta certificada en BPM. ¿Qué marco rige ese laboratorio?» La respuesta correcta se apoya en lo siguiente: El control de calidad del fabricante hace parte de las BPM (Resolución 1160 de 2016). La Resolución 3619 de 2013 expidió el manual de BPL de control de calidad y exige el certificado de BPL a los laboratorios externos. La fuente citada es: Resolución 1160 de 2016; Resolución 3619 de 2013, artículo 2.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos y marco normativo de las BPL y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe comparativo de marcos de calidad con recomendaciones.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar resolución 3619 de 2013: estructura y alcance, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y describe qué hace cada laboratorio. Evidencia que debe quedar: Registro del paso.","Compara cuatro marcos: BPL de control de calidad (Resolución 3619), BPL de la OCDE, ISO/IEC 17025 y BPM, por alcance, autoridad u organismo y obligatoriedad. Evidencia que debe quedar: Registro del paso.","Asigna a cada laboratorio el marco obligatorio y los voluntarios que le convendrían. Evidencia que debe quedar: Registro del paso.","Explica quién verifica cada marco (Invima, ONAC u otro) y con qué resultado (certificado o acreditación). Evidencia que debe quedar: Registro del paso.","Señala un error frecuente de interpretación para cada caso. Evidencia que debe quedar: Registro del paso.","Escribe una recomendación breve para cada consultante. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confundir el análisis final con la garantía de calidad Corrección: el muestreo no detecta todos los defectos; la calidad se construye durante el proceso.","Error: documentar después de ejecutar Corrección: el registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad.","Error: copiar un procedimiento de otra planta Corrección: el procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar resolución 3619 de 2013: estructura y alcance en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Resolución 3619 de 2013: estructura y alcance»?","respuesta":"Describe la estructura del Manual de BPL de control de calidad (Anexo 1) y la guía de evaluación (Anexo 2), y a quién aplica en Colombia."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe comparativo de marcos de calidad con recomendaciones.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Resolución 3619 de 2013: estructura y alcance se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos y marco normativo de las BPL.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"Resolución 3619 de 2013 – Manual de BPL de control de calidad de productos farmacéuticos y guía de evaluación. INVIMA / MinSalud (ES)","url":"https://www.invima.gov.co/sites/default/files/resolucion-3619-de-2013.pdf"},{"cita":"[Página web] Resolución 3619 de 2013 (texto compilado en el Normograma INVIMA). Normograma INVIMA (ES)","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_3619_2013.htm"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente resolución 3619 de 2013: estructura y alcance en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de resolución 3619 de 2013: estructura y alcance"}],"keywords":["curso","buenas","prácticas","laboratorio","resolución","estructura","alcance","unidad","fundamentos","marco","normativo"],"mapa":{"centro":"Resolución 3619 de 2013: estructura y alcance","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 1. Fundamentos y marco normativo de las BPL","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se aplica: Marco de calidad para cuatro laboratorios","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y describe qué hace cada laboratorio.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Compara cuatro marcos: BPL de control de calidad (Resolución 3619), BPL de la OCDE, ISO/IEC 17025 y BPM, por alcance, autoridad u organismo y obligatoriedad.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Asigna a cada laboratorio el marco obligatorio y los voluntarios que le convendrían.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Explica quién verifica cada marco (Invima, ONAC u otro) y con qué resultado (certificado o acreditación).","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Señala un error frecuente de interpretación para cada caso.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Escribe una recomendación breve para cada consultante.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Resolución 3619 de 2013: estructura y alcance","contexto":"En una planta o un laboratorio farmacéutico colombiano, el equipo analiza este caso de unidad 1. Fundamentos y marco normativo de las BPL: Una consultora ficticia recibe cuatro consultas (datos simulados): (1) el laboratorio de control de calidad interno de un fabricante de tabletas; (2) un laboratorio externo que analizará muestras de varios fabricantes; (3) un centro que hará estudios de toxicidad en animales para un dossier de una molécula nueva; (4) un laboratorio que calibra balanzas y termómetros para la industria. Cada uno pregunta qué marco de calidad debe cumplir, quién lo verifica y si es obligatorio u opcional. La pregunta que decide esta clase es: Un fabricante tiene su propio laboratorio de control dentro de la planta certificada en BPM. ¿Qué marco rige ese laboratorio?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Las BPM de la Resolución 1160; el certificado de BPL de la Resolución 3619 se exige a los externos.","correcta":true,"retro":"Correcto. La Resolución 3619 exige el certificado de BPL a los laboratorios externos."},{"texto":"Solo la ISO/IEC 17025, porque es la única norma obligatoria para cualquier laboratorio de ensayo en Colombia.","correcta":false,"retro":"La ISO/IEC 17025 es voluntaria."},{"texto":"Los principios de la OCDE, porque todo laboratorio farmacéutico hace estudios de seguridad.","correcta":false,"retro":"Un laboratorio de control no hace estudios no clínicos de seguridad."},{"texto":"Ninguno, porque los laboratorios internos de las plantas están exentos de requisitos sanitarios.","correcta":false,"retro":"El laboratorio interno está cubierto por las BPM del fabricante."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
