    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 30. Seguridad química: SGA, fichas de seguridad, almacenamiento y EPP
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Seguridad química: SGA, fichas de seguridad, almacenamiento y EPP$t$
     AND m.title = $u$Unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Seguridad química: SGA, fichas de seguridad, almacenamiento y EPP$t$, $u$Unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Seguridad química: SGA, fichas de seguridad, almacenamiento y EPP","texto":"En una planta o un laboratorio farmacéutico colombiano, un lote cumple las especificaciones, pero la revisión del expediente muestra una etapa sin verificar. Lo que está en juego es el criterio de seguridad química: SGA, fichas de seguridad, almacenamiento y EPP. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar seguridad química: SGA, fichas de seguridad, almacenamiento y EPP con tus propias palabras y reconocer por qué importa en curso de Buenas Prácticas de Laboratorio — BPL.","Relacionar seguridad química: SGA, fichas de seguridad, almacenamiento y EPP con unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar seguridad química: SGA, fichas de seguridad, almacenamiento y EPP y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Aplica el SGA, las fichas de datos de seguridad, la compatibilidad de almacenamiento y la jerarquía de controles. aplicar medidas de seguridad química en el laboratorio: Sistema Globalmente Armonizado (SGA), fichas de datos de seguridad, almacenamiento compatible y elementos de protección personal. además del riesgo biológico, el laboratorio de control de calidad maneja solventes inflamables (metanol, acetonitrilo), ácidos y bases concentrados, oxidantes y sustancias tóxicas.…"},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, seguridad química: SGA, fichas de seguridad, almacenamiento y EPP aparece en medio de una decisión que no admite improvisación: un lote cumple las especificaciones, pero la revisión del expediente muestra una etapa sin verificar. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA. El objetivo del curso es claro: Que el Químico Farmacéutico implemente, mantenga y demuestre ante el INVIMA y el ONAC el cumplimiento de las Buenas Prácticas de Laboratorio en un laboratorio de control de calidad farmacéutico, asegurando resultados analíticos confiables, trazables y seguros. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Aplica el SGA, las fichas de datos de seguridad, la compatibilidad de almacenamiento y la jerarquía de controles. aplicar medidas de seguridad química en el laboratorio: Sistema Globalmente Armonizado (SGA), fichas de datos de seguridad, almacenamiento compatible y elementos de protección personal. además del riesgo biológico, el laboratorio de control de calidad maneja solventes inflamables (metanol, acetonitrilo), ácidos y bases concentrados, oxidantes y sustancias tóxicas.…","Una pregunta que se usa para comprobar esta clase es: «Un analista quiere guardar ácido nítrico concentrado junto al etanol en el mismo gabinete porque «los dos son líquidos». ¿Qué le respondes?» La respuesta correcta se apoya en lo siguiente: El almacenamiento químico se organiza por compatibilidad según el SGA y las fichas de datos de seguridad: un oxidante fuerte como el ácido nítrico concentrado no se guarda con inflamables como el etanol. La fuente citada es: Sistema Globalmente Armonizado (SGA); fichas de datos de seguridad.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar seguridad química: SGA, fichas de seguridad, almacenamiento y EPP, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Definir el requisito. Identifica la norma, el procedimiento o la especificación aplicable y escribe el criterio antes de mirar el dato. Evidencia que debe quedar: Requisito citado por su nombre.","Reunir la evidencia. Localiza registros, resultados, certificados y firmas que correspondan al caso concreto, no a un lote parecido. Evidencia que debe quedar: Expediente del caso.","Comparar contra el criterio. Evalúa la evidencia con el criterio definido; separa lo que cumple de lo que no y documenta las diferencias. Evidencia que debe quedar: Lista de verificación.","Evaluar el impacto. Decide si la diferencia afecta la seguridad, la eficacia, la calidad o la validez del dato, y a qué lotes alcanza. Evidencia que debe quedar: Evaluación de impacto.","Actuar y verificar. Corrige, previene, asigna responsable y fecha, y comprueba con evidencia que la acción funcionó. Evidencia que debe quedar: CAPA cerrada y verificada.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confundir el análisis final con la garantía de calidad Corrección: el muestreo no detecta todos los defectos; la calidad se construye durante el proceso.","Error: documentar después de ejecutar Corrección: el registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad.","Error: copiar un procedimiento de otra planta Corrección: el procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar seguridad química: SGA, fichas de seguridad, almacenamiento y EPP en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Seguridad química: SGA, fichas de seguridad, almacenamiento y EPP»?","respuesta":"Aplica el SGA, las fichas de datos de seguridad, la compatibilidad de almacenamiento y la jerarquía de controles. aplicar medidas de seguridad química en el laboratorio: Sistema Globalmente Armonizado (SGA), fichas de datos de seguridad, almacenamiento compatible y elementos de protección personal. además del riesgo biológico, el laboratorio de control de calidad maneja solventes inflamables (metanol, acetonitrilo), ácidos y bases concentrados, oxidantes y sustancias tóxicas.…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Seguridad química: SGA, fichas de seguridad, almacenamiento y EPP se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"Sistema Globalmente Armonizado (SGA): aprende a interpretar etiquetas y pictogramas químicos","url":"https://www.youtube.com/watch?v=kNTWTSf7ZAA"},{"cita":"Resolución 0773 de 2021 – Aplicación del SGA en lugares de trabajo. MinTrabajo y MinSalud (copia CCS) (ES)","url":"https://ccs.org.co/wp-content/uploads/2023/01/RES0773SGA.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente seguridad química: SGA, fichas de seguridad, almacenamiento y EPP en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de seguridad química: SGA, fichas de seguridad, almacenamiento y EPP"}],"keywords":["curso","buenas","prácticas","laboratorio","seguridad","química","fichas","almacenamiento","unidad","bioseguridad","residuos","peligrosos"],"mapa":{"centro":"Seguridad química: SGA, fichas de seguridad, almacenamiento y EPP","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Definir el requisito","Reunir la evidencia","Comparar contra el criterio"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Requisito citado por su nombre","Expediente del caso","Lista de verificación"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se sostiene una decisión de calidad","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Definir el requisito","detalle":"Identifica la norma, el procedimiento o la especificación aplicable y escribe el criterio antes de mirar el dato.","icono":"Search","evidencia":"Requisito citado por su nombre"},{"titulo":"Reunir la evidencia","detalle":"Localiza registros, resultados, certificados y firmas que correspondan al caso concreto, no a un lote parecido.","icono":"ClipboardList","evidencia":"Expediente del caso"},{"titulo":"Comparar contra el criterio","detalle":"Evalúa la evidencia con el criterio definido; separa lo que cumple de lo que no y documenta las diferencias.","icono":"Workflow","evidencia":"Lista de verificación"},{"titulo":"Evaluar el impacto","detalle":"Decide si la diferencia afecta la seguridad, la eficacia, la calidad o la validez del dato, y a qué lotes alcanza.","icono":"FileCheck","evidencia":"Evaluación de impacto"},{"titulo":"Actuar y verificar","detalle":"Corrige, previene, asigna responsable y fecha, y comprueba con evidencia que la acción funcionó.","icono":"RefreshCw","evidencia":"CAPA cerrada y verificada"}]},"caso":{"titulo":"Seguridad química: SGA, fichas de seguridad, almacenamiento y EPP","contexto":"En una planta o un laboratorio farmacéutico colombiano, el equipo analiza este caso de unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA: una situación que exige documentar la decisión. La pregunta que decide esta clase es: Un analista quiere guardar ácido nítrico concentrado junto al etanol en el mismo gabinete porque «los dos son líquidos». ¿Qué le respondes?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Sí, porque ambos son líquidos de uso común en el laboratorio de análisis fisicoquímico e instrumental.","correcta":false,"retro":"Ser líquidos no los hace compatibles."},{"texto":"Sí, siempre que ambos frascos estén bien cerrados y rotulados con su nombre y su fecha.","correcta":false,"retro":"Cerrar y rotular no elimina la incompatibilidad."},{"texto":"Sí, siempre que el gabinete tenga extractor de vapores y permanezca bajo llave.","correcta":false,"retro":"La extracción no previene una reacción entre incompatibles."},{"texto":"No: son incompatibles (oxidante fuerte e inflamable); se almacenan separados según la ficha de seguridad.","correcta":true,"retro":"Correcto. La ficha de datos de seguridad indica las incompatibilidades."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 31. Marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud$t$
     AND m.title = $u$Unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud$t$, $u$Unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud","texto":"En una planta o un laboratorio farmacéutico colombiano, un indicador empeora durante tres meses y nadie sabe explicar por qué. Lo que está en juego es el criterio de marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud con tus propias palabras y reconocer por qué importa en curso de Buenas Prácticas de Laboratorio — BPL.","Relacionar marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud con unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Interpreta las obligaciones del generador de residuos peligrosos (Decreto 4741/2005, compilado en el Decreto 1076/2015) y el marco de residuos de atención en salud (Res. 1164/2002, Decreto 780/2016)."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud aparece en medio de una decisión que no admite improvisación: un indicador empeora durante tres meses y nadie sabe explicar por qué. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA. El objetivo del curso es claro: Que el Químico Farmacéutico implemente, mantenga y demuestre ante el INVIMA y el ONAC el cumplimiento de las Buenas Prácticas de Laboratorio en un laboratorio de control de calidad farmacéutico, asegurando resultados analíticos confiables, trazables y seguros. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Interpreta las obligaciones del generador de residuos peligrosos (Decreto 4741/2005, compilado en el Decreto 1076/2015) y el marco de residuos de atención en salud (Res. 1164/2002, Decreto 780/2016).","Una pregunta que se usa para comprobar esta clase es: «Un laboratorio entrega sus residuos de acetonitrilo y metanol con la basura común porque «son pocos litros al mes». ¿Qué análisis es correcto?» La respuesta correcta se apoya en lo siguiente: Los residuos de solventes son residuos peligrosos. El generador debe identificarlos, segregarlos, almacenarlos de forma segura y entregarlos a un gestor autorizado, conforme al Decreto 4741 de 2005, compilado en el Decreto 1076 de 2015. La fuente citada es: Decreto 4741 de 2005 (compilado en el Decreto 1076 de 2015).. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Definir el requisito. Identifica la norma, el procedimiento o la especificación aplicable y escribe el criterio antes de mirar el dato. Evidencia que debe quedar: Requisito citado por su nombre.","Reunir la evidencia. Localiza registros, resultados, certificados y firmas que correspondan al caso concreto, no a un lote parecido. Evidencia que debe quedar: Expediente del caso.","Comparar contra el criterio. Evalúa la evidencia con el criterio definido; separa lo que cumple de lo que no y documenta las diferencias. Evidencia que debe quedar: Lista de verificación.","Evaluar el impacto. Decide si la diferencia afecta la seguridad, la eficacia, la calidad o la validez del dato, y a qué lotes alcanza. Evidencia que debe quedar: Evaluación de impacto.","Actuar y verificar. Corrige, previene, asigna responsable y fecha, y comprueba con evidencia que la acción funcionó. Evidencia que debe quedar: CAPA cerrada y verificada.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: cerrar una CAPA sin verificar eficacia Corrección: una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato.","Error: tratar todos los riesgos como iguales Corrección: priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto.","Error: copiar un procedimiento de otra planta Corrección: el procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud»?","respuesta":"Interpreta las obligaciones del generador de residuos peligrosos (Decreto 4741/2005, compilado en el Decreto 1076/2015) y el marco de residuos de atención en salud (Res. 1164/2002, Decreto 780/2016)."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"Gestión integral de residuos peligrosos. Módulo 1 Decreto 4741 de 2005 - Capítulo 1","url":"https://www.youtube.com/watch?v=h64_lSIrEDQ"},{"cita":"Atica: ¿Cómo gestionar residuos peligrosos en Colombia?","url":"https://www.youtube.com/watch?v=tn-XNqIVrmI"},{"cita":"Decreto 4741 de 2005 – Prevención y manejo de residuos o desechos peligrosos. Gobierno de Colombia (copia Alcaldía de Bogotá) (ES)","url":"https://bogota.gov.co/sites/default/files/inline-files/decreto_4741_de_2005.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud"}],"keywords":["curso","buenas","prácticas","laboratorio","marco","legal","residuos","peligrosos","decreto","gestión","salud","unidad"],"mapa":{"centro":"Marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Definir el requisito","Reunir la evidencia","Comparar contra el criterio"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Requisito citado por su nombre","Expediente del caso","Lista de verificación"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se sostiene una decisión de calidad","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Definir el requisito","detalle":"Identifica la norma, el procedimiento o la especificación aplicable y escribe el criterio antes de mirar el dato.","icono":"Search","evidencia":"Requisito citado por su nombre"},{"titulo":"Reunir la evidencia","detalle":"Localiza registros, resultados, certificados y firmas que correspondan al caso concreto, no a un lote parecido.","icono":"ClipboardList","evidencia":"Expediente del caso"},{"titulo":"Comparar contra el criterio","detalle":"Evalúa la evidencia con el criterio definido; separa lo que cumple de lo que no y documenta las diferencias.","icono":"Workflow","evidencia":"Lista de verificación"},{"titulo":"Evaluar el impacto","detalle":"Decide si la diferencia afecta la seguridad, la eficacia, la calidad o la validez del dato, y a qué lotes alcanza.","icono":"FileCheck","evidencia":"Evaluación de impacto"},{"titulo":"Actuar y verificar","detalle":"Corrige, previene, asigna responsable y fecha, y comprueba con evidencia que la acción funcionó.","icono":"RefreshCw","evidencia":"CAPA cerrada y verificada"}]},"caso":{"titulo":"Marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud","contexto":"En una planta o un laboratorio farmacéutico colombiano, el equipo analiza este caso de unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA: una situación que exige documentar la decisión. La pregunta que decide esta clase es: Un laboratorio entrega sus residuos de acetonitrilo y metanol con la basura común porque «son pocos litros al mes». ¿Qué análisis es correcto?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Son residuos peligrosos: se segregan y se entregan a un gestor autorizado, sin importar el volumen.","correcta":true,"retro":"Correcto. El volumen influye en otras obligaciones, no en el carácter peligroso."},{"texto":"Es aceptable si los solventes se diluyen con suficiente agua antes de entregarlos al servicio de aseo.","correcta":false,"retro":"Diluir no elimina el carácter peligroso ni está permitido como disposición."},{"texto":"Es aceptable, porque los generadores pequeños están exentos de toda obligación sobre sus residuos.","correcta":false,"retro":"El tamaño del generador cambia algunas obligaciones, pero no permite la disposición común."},{"texto":"Es un problema solo si los solventes están contaminados con microorganismos del laboratorio.","correcta":false,"retro":"Los solventes son peligrosos por sus propiedades químicas, no solo biológicas."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 32. Segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio$t$
     AND m.title = $u$Unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio$t$, $u$Unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio","texto":"En una planta o un laboratorio farmacéutico colombiano, un lote cumple las especificaciones, pero la revisión del expediente muestra una etapa sin verificar. Lo que está en juego es el criterio de segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio con tus propias palabras y reconocer por qué importa en curso de Buenas Prácticas de Laboratorio — BPL.","Relacionar segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio con unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Ejecuta la clasificación, segregación por código de colores, almacenamiento temporal y entrega a gestor autorizado de los residuos del laboratorio."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio aparece en medio de una decisión que no admite improvisación: un lote cumple las especificaciones, pero la revisión del expediente muestra una etapa sin verificar. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA. El objetivo del curso es claro: Que el Químico Farmacéutico implemente, mantenga y demuestre ante el INVIMA y el ONAC el cumplimiento de las Buenas Prácticas de Laboratorio en un laboratorio de control de calidad farmacéutico, asegurando resultados analíticos confiables, trazables y seguros. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Ejecuta la clasificación, segregación por código de colores, almacenamiento temporal y entrega a gestor autorizado de los residuos del laboratorio.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en requisito y en evidencia documentada, no en la intuición.","La clase pertenece a unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Definir el requisito. Identifica la norma, el procedimiento o la especificación aplicable y escribe el criterio antes de mirar el dato. Evidencia que debe quedar: Requisito citado por su nombre.","Reunir la evidencia. Localiza registros, resultados, certificados y firmas que correspondan al caso concreto, no a un lote parecido. Evidencia que debe quedar: Expediente del caso.","Comparar contra el criterio. Evalúa la evidencia con el criterio definido; separa lo que cumple de lo que no y documenta las diferencias. Evidencia que debe quedar: Lista de verificación.","Evaluar el impacto. Decide si la diferencia afecta la seguridad, la eficacia, la calidad o la validez del dato, y a qué lotes alcanza. Evidencia que debe quedar: Evaluación de impacto.","Actuar y verificar. Corrige, previene, asigna responsable y fecha, y comprueba con evidencia que la acción funcionó. Evidencia que debe quedar: CAPA cerrada y verificada.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En un laboratorio ficticio, los residuos de fase móvil del HPLC (acetonitrilo, metanol y soluciones tampón) se vierten al lavamanos «porque se diluyen con el agua», y los medios de cultivo usados se botan en bolsas comunes después de cerrarlas bien. Un practicante pregunta si eso es correcto (datos simulados). No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: tratar todos los riesgos como iguales Corrección: priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto.","Error: copiar un procedimiento de otra planta Corrección: el procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso.","Error: cerrar una CAPA sin verificar eficacia Corrección: una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio»?","respuesta":"Ejecuta la clasificación, segregación por código de colores, almacenamiento temporal y entrega a gestor autorizado de los residuos del laboratorio."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"Guía para la Gestión de Residuos Peligrosos en Laboratorios","url":"https://www.youtube.com/watch?v=QkdVxhBiTk0"},{"cita":"Gestión de residuos del laboratorio","url":"https://www.youtube.com/watch?v=XOCvgLfEDek"},{"cita":"Módulo 7: Gestión de Residuos Químicos (1) Clasificación","url":"https://www.youtube.com/watch?v=giWr1JyYB2M"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio"}],"keywords":["curso","buenas","prácticas","laboratorio","segregación","almacenamiento","disposición","residuos","químicos","biológicos","unidad","bioseguridad"],"mapa":{"centro":"Segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Definir el requisito","Reunir la evidencia","Comparar contra el criterio"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Requisito citado por su nombre","Expediente del caso","Lista de verificación"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se sostiene una decisión de calidad","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Definir el requisito","detalle":"Identifica la norma, el procedimiento o la especificación aplicable y escribe el criterio antes de mirar el dato.","icono":"Search","evidencia":"Requisito citado por su nombre"},{"titulo":"Reunir la evidencia","detalle":"Localiza registros, resultados, certificados y firmas que correspondan al caso concreto, no a un lote parecido.","icono":"ClipboardList","evidencia":"Expediente del caso"},{"titulo":"Comparar contra el criterio","detalle":"Evalúa la evidencia con el criterio definido; separa lo que cumple de lo que no y documenta las diferencias.","icono":"Workflow","evidencia":"Lista de verificación"},{"titulo":"Evaluar el impacto","detalle":"Decide si la diferencia afecta la seguridad, la eficacia, la calidad o la validez del dato, y a qué lotes alcanza.","icono":"FileCheck","evidencia":"Evaluación de impacto"},{"titulo":"Actuar y verificar","detalle":"Corrige, previene, asigna responsable y fecha, y comprueba con evidencia que la acción funcionó.","icono":"RefreshCw","evidencia":"CAPA cerrada y verificada"}]},"caso":{"titulo":"Segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio","contexto":"En un laboratorio ficticio, los residuos de fase móvil del HPLC (acetonitrilo, metanol y soluciones tampón) se vierten al lavamanos «porque se diluyen con el agua», y los medios de cultivo usados se botan en bolsas comunes después de cerrarlas bien. Un practicante pregunta si eso es correcto (datos simulados).","pregunta":"¿Qué decisión demuestra que entendiste segregación, almacenamiento y disposición de residuos químicos y biológicos del laboratorio?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
