  -- 34. Clasificación de no conformidades basada en riesgo
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Clasificación de no conformidades basada en riesgo$t$
     AND m.title = $u$Unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA$u$
